      "proposed_laureates": [
        "Charles L. Kane",
        "Laurens W. Molenkamp",
        "Qi-Kun Xue"
      ],
      "assessment": {
        "nobel_worthiness": "The prediction and experimental realization of topological insulating phases established a major new framework for quantum matter, with lasting influence across condensed matter physics.",
        "attribution": "Kane's theory and the experimental demonstrations associated with Molenkamp and Xue give this selection a strong theory-experiment structure. The ballot groups several related effects, so the prize's central contribution would need careful definition.",
        "maturity": "The effects have been studied across multiple material systems for many years, with substantial experimental confirmation.",
        "uncertainties": [
          "The ballot combines quantum spin Hall and quantum anomalous Hall effects, whose discoveries and experimental milestones do not map neatly to one three-person attribution."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B008",
      "proposed_laureates": [
        "Christian Pfleiderer",
        "Roland Wiesendanger",
        "Yoshinori Tokura"
      ],
      "assessment": {
        "nobel_worthiness": "Magnetic skyrmions revealed topologically structured spin textures in real materials and opened a rich area of fundamental and applied magnetism.",
        "attribution": "The proposed names represent important routes through bulk materials, imaging, and materials discovery. The field developed through multiple groups, so the specific experimental milestones behind this grouping should be distinguished.",
        "maturity": "Skyrmions have been observed and characterized in varied systems over many years; their proposed device uses remain less mature than the basic discovery.",
        "uncertainties": [
          "The discovery is distributed across materials and techniques, making the boundary of the prize contribution debatable."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B022",
      "proposed_laureates": [
        "Antoine Georges",
        "Dieter Vollhardt",
        "Gabriel Kotliar"
      ],
      "assessment": {
        "nobel_worthiness": "Dynamical mean-field theory became a powerful framework for understanding correlated electrons and has materially improved the quantitative interpretation of complex solids.",
        "attribution": "These theorists are central contributors to the method and its development. Credit should recognize the broader foundational community while identifying their distinct roles.",
        "maturity": "The framework has been established for decades, tested against experiments, and extended well beyond its original applications.",
        "uncertainties": [
          "A theory-method prize would need to specify which advances constitute the decisive contribution and how to represent the wider collaboration."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B006",
      "proposed_laureates": [
        "Nicola A. Spaldin",
        "Ramamoorthy Ramesh",
        "Yoshinori Tokura"
      ],
      "assessment": {
        "nobel_worthiness": "Multiferroics brought coupled electric and magnetic order into renewed focus and exposed important interactions in correlated materials, with potential for new device functions.",
        "attribution": "Spaldin's theoretical work and the experimental advances associated with Ramesh and Tokura provide complementary contributions. The broad label spans a long history, so the prize would need a specific discovery at its center.",
        "maturity": "The underlying physics is well established across many compounds, although practical applications remain more limited than the scientific impact.",
        "uncertainties": [
          "The field includes several distinct discoveries and contributors beyond the three proposed names."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B020",
      "proposed_laureates": [
        "John J. Croat",
        "Masato Sagawa"
      ],
      "assessment": {
        "nobel_worthiness": "Nd-Fe-B permanent magnets transformed magnetic materials and underpin widespread technologies. This is a clear, durable materials discovery with exceptional practical impact.",
        "attribution": "Croat and Sagawa are associated with independent, near-simultaneous development of the material, making a two-person attribution plausible.",
        "maturity": "The material has been produced and used globally for decades, with its magnetic performance repeatedly demonstrated.",
        "uncertainties": [
          "The independent development histories and contributions of associated industrial teams need to be delineated precisely."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B013",
      "proposed_laureates": [
        "Claudio Castelnovo",
        "Roderich Moessner",
        "Shivaji L. Sondhi"
      ],
      "assessment": {
        "nobel_worthiness": "The prediction of emergent magnetic monopole-like excitations in spin ice was a striking demonstration that collective behavior in solids can produce effective particles unlike the microscopic constituents.",
        "attribution": "The proposed theorists are central to the monopole interpretation and its development. Experimental observation and characterization involved additional researchers.",
        "maturity": "The spin-ice phenomenology has been studied extensively, though the monopoles are emergent quasiparticles rather than isolated fundamental magnetic charges.",
        "uncertainties": [
          "The relation between the theoretical prediction and the experimental evidence should be framed carefully, including the contributions of experimental groups."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B024",
      "proposed_laureates": [
        "Hideo Hosono",
        "Igor I. Mazin"
      ],
      "assessment": {
        "nobel_worthiness": "The discovery of iron-based high-temperature superconductors opened a major new materials family and renewed fundamental questions about unconventional superconductivity.",
        "attribution": "Hosono's material discovery is clear; Mazin's theory helped interpret the new class. Their roles are complementary but represent different parts of a broader international effort.",
        "maturity": "The family and its superconducting behavior have been studied for many years, but a settled microscopic explanation remains absent.",
        "uncertainties": [
          "The proposed pairing combines discovery of the materials with theoretical interpretation, and the exact prize contribution may be narrower."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B004",
      "proposed_laureates": [
        "Jie Shan",
        "Kin Fai Mak",
        "Long Ju"
      ],
      "assessment": {
        "nobel_worthiness": "The fractional quantum anomalous Hall effect in moiré materials could provide a consequential realization of strongly interacting topological phases without an applied magnetic field.",
        "attribution": "The named researchers are associated with important experimental advances, but the field is developing rapidly and contributions from multiple groups may prove central.",
        "maturity": "The result is recent. Independent confirmation, robustness across devices and materials, and a fuller understanding of the observed phases are still important.",
        "uncertainties": [
          "The experimental record and attribution are not yet settled enough for high confidence in a prize at this stage."
        ]
      }
    }
  ]
